<template>
  <main class="video-editor">
    <header class="editor-header"><div class="project-title"><router-link to="/?media=video">← 图库</router-link><strong>{{project?.name||'视频工作台'}}</strong><span>v{{revision}} · 24 fps</span></div><div class="header-actions"><span class="save-state">{{busy?'正在提交…':pendingOperation?'提交结果待确认':lease?'独占剪辑':annotation?'多人字幕 / 贴图 · 已自动保存':'只读查看'}}</span><button v-if="!lease && !annotation" :disabled="locked || members.length>0" @click="acquire">独占剪辑</button><button v-if="!lease && !annotation && project?.space_id" :disabled="locked" @click="joinAnnotations">加入多人字幕 / 贴图（{{members.length}}/5）</button><button v-if="annotation" :disabled="locked" @click="leaveAnnotations">退出多人编辑</button><template v-if="lease"><button :disabled="locked" @click="handoffOpen=true">交接编辑权</button><button :disabled="locked" @click="release">释放</button></template><button class="accent" :disabled="!lease||locked" @click="exportVideo">导出 MP4</button></div></header>
    <router-link v-if="!viewUnavailable" class="native-link" :to="`/video/hypit/${id}`">打开完整 Hypit 工程 → 源文件、语义组件、评论与产物</router-link>
    <a-alert v-if="members.length" :message="`字幕 / 贴图协作中：${members.map(m=>m.name || m.userId).join('、')}。视频剪辑需等成员退出。`" type="info" show-icon/><a-alert v-if="error" :message="error" type="error" show-icon closable @close="error=''"/>
    <section v-if="pendingOperation" class="pending-operation">
      <a-alert type="warning" show-icon message="提交结果尚未确认。重试原请求可核对结果，不会重复添加字幕或贴图。" />
      <button :disabled="busy" @click="retryOperation">重试原请求</button>
      <button :disabled="busy" @click="abandonOperation">停止重试并核对最新</button>
    </section>
    <section v-if="draftDirty && draft && !selected" style="max-width:640px;padding:16px">
      <a-alert type="warning" show-icon :message="viewUnavailable?'当前无法查看该工程。未保存的本地属性仍保留，可复制核对。':'该片段已被其他成员删除，未保存的本地属性仍保留，可核对后重新添加。'" />
      <p>{{ draft.name }} · {{ draft.at }} 帧开始 · {{ draft.length }} 帧</p>
      <label v-if="draft.kind==='text'">保留的本地文字<textarea :value="draft.text" readonly style="width:100%" /></label>
      <button :disabled="locked" @click="draft=undefined;draftOriginal='';selectedId=''">{{viewUnavailable?'放弃本地草稿':'放弃已删除片段的本地草稿'}}</button>
    </section>
    <a-spin :spinning="loading">
    <div v-if="state" class="editor-body" :class="{'studio-mode':previewMode==='hypit'}">
      <aside class="asset-panel"><div class="panel-heading">项目素材 <span>{{assets.length}}</span></div><button class="wide" :disabled="uploading" @click="fileInput?.click()">{{uploading?'正在处理并保存…':'+ 上传视频 / 图片 / 音频'}}</button><input ref="fileInput" type="file" accept="video/*,image/*,audio/*" multiple hidden @change="uploadAssets"/><div class="import-row"><input v-model="pictureId" placeholder="图库图片 ID"/><button @click="importImage">导入</button></div><div class="asset-list"><div v-for="asset in assets" :key="asset.id" class="asset" @pointerdown="beginAssetDrag($event,asset.id)" @dblclick="insertAsset(asset)"><img draggable="false" v-if="asset.posterKey" :src="assetMedia(id,asset.id,'poster')" :alt="asset.name"/><div v-else class="audio-symbol">♫</div><div><strong>{{asset.name}}</strong><small>{{asset.kind==='image'?'图像':frameTime(asset.frames)}} · {{asset.kind}}</small></div><button title="插入素材" :disabled="(!lease && !(annotation && asset.kind==='image'))||locked" @click="insertAsset(asset)">+</button></div></div><details class="model-panel"><summary>生成素材</summary><select v-model="modelTool" aria-label="生成模型"><option value="generate_image">Qwen 图像生成 / 编辑</option><option value="generate_video">LTX 视频生成</option><option value="synthesize_speech">IndexTTS 配音</option></select><label v-if="modelTool==='generate_video'">单段时长<select v-model="modelFrames" aria-label="视频生成帧数"><option :value="49">约 2 秒（49 帧）</option><option :value="121">约 5 秒（121 帧）</option><option :value="193">约 8 秒（193 帧）</option><option :value="257">约 10.7 秒（257 帧，上限）</option></select><small>单段最多 257 帧；更长视频请分段生成后拼接。</small></label><textarea aria-label="生成描述" v-model="modelPrompt" :placeholder="modelTool==='synthesize_speech'?'输入配音文本':'描述想要生成的素材'"/><select v-if="modelTool==='synthesize_speech'" v-model="voiceName"><option v-for="voice in voiceOptions" :key="voice" :value="voice">{{voice}}</option></select><select v-model="referenceAssetId" aria-label="参考素材"><option value="">无参考素材</option><option v-for="asset in assets.filter(a=>modelTool==='synthesize_speech'?a.hasAudio:a.kind==='image')" :key="asset.id" :value="asset.id">参考：{{asset.name}}</option></select><button :disabled="!lease||locked||!modelPrompt.trim()" @click="generate">生成到素材库</button></details></aside>
      <section class="central-panel"><div class="preview-heading"><div class="preview-tabs"><button :class="{active:previewMode==='live'}" @click="previewMode='live'">剪辑预览</button><button :class="{active:previewMode==='hypit'}" @click="previewMode='hypit'">Hypit Studio</button></div><select aria-label="输出画幅" :value="state.width>state.height?'landscape':'portrait'" :disabled="!lease||locked" @change="changeAspect"><option value="landscape">横屏 1280 × 720</option><option value="portrait">竖屏 720 × 1280</option></select></div><div class="preview-stage" :class="{'studio-stage':previewMode==='hypit'}"><VideoPreview v-if="previewMode==='live'" :state="state" :project-id="id" :frame="playhead" :playing="playing"/><iframe v-else :key="studioKey" ref="studioFrame" :src="`${videoBase}/projects/${id}/studio/`" title="Hypit Studio" @load="studioLoaded"/></div><div class="transport"><button @click="playing=!playing">{{playing?'暂停':'播放'}}</button><input type="range" aria-label="播放头" min="0" :max="duration" v-model.number="playhead" @input="playing=false"/><span>{{frameTime(playhead)}} / {{frameTime(duration)}} · {{playhead}}f</span></div>
      <div class="timeline-toolbar"><div><button :disabled="!lease||!undo.length||locked" @click="undoEdit">撤销</button><button :disabled="!lease||!redo.length||locked" @click="redoEdit">重做</button><button :disabled="!canEditSelected||locked" @click="split">分割</button><button :disabled="!canEditSelected||locked" @click="operate([{type:'duplicate_clip',clipId:selected!.id}])">复制</button><button :disabled="!canEditSelected||locked" @click="operate([{type:'delete_clip',clipId:selected!.id}])">删除</button><button :disabled="(!lease && !annotation)||locked" @click="addTitle">+ 文字</button></div><div><select v-model="trackKind"><option value="visual">画面轨</option><option value="audio">音频轨</option><option value="text">文字轨</option></select><button :disabled="!lease||locked" @click="operate([{type:'add_track',kind:trackKind,name:trackKind==='visual'?'画面':trackKind==='audio'?'音频':'文字'}])">+ 轨道</button><input type="range" aria-label="时间线缩放" min="1" max="8" step=".5" v-model.number="zoom"/></div></div>
      <div class="timeline-scroll" ref="timelineElement"><div class="timeline-inner" :style="{width:`${Math.max(700,duration*zoom+180)}px`}"><div class="ruler"><span class="ruler-label">时间 / 秒</span><div class="ruler-line" @click="seekFromRuler"><span v-for="second in Math.ceil(duration/24)" :key="second" :style="{left:`${(second-1)*24*zoom}px`}">{{second-1}}</span></div></div><div v-for="(track,index) in state.tracks" :key="track.id" class="track" :style="{height:`${clipRows.heights.get(track.id)||44}px`}"><div class="track-label"><strong>{{track.name}}</strong><div><button :disabled="!lease||locked||index===0" @click="operate([{type:'reorder_track',trackId:track.id,index:index-1}])">↑</button><button :disabled="!lease||locked||index===state.tracks.length-1" @click="operate([{type:'reorder_track',trackId:track.id,index:index+1}])">↓</button></div></div><div class="track-lane" :data-track="track.id" @dragover.prevent @drop="dropAsset($event,track.id)" @click.self="seekFromRuler"><div v-for="clip in state.clips.filter(c=>c.trackId===track.id)" :key="clip.id" class="timeline-clip" role="button" tabindex="0" :aria-label="`${clip.text||clip.name}，${clip.at}帧开始，${clip.length}帧`" @keydown.enter.prevent.stop="select(clip)" @keydown.space.prevent.stop="select(clip)" :class="[clip.kind,{selected:clip.id===selectedId,muted:clip.muted}]" :style="clipStyle(clip)" @pointerdown="beginDrag($event,clip,'move')" @click.stop="select(clip)"><span class="trim-handle start" @pointerdown.stop="beginDrag($event,clip,'left')"/><span class="clip-name">{{clip.text||clip.name}} {{clip.link?'⌁':''}}</span><span class="trim-handle end" @pointerdown.stop="beginDrag($event,clip,'right')"/></div><div class="playhead" :style="{left:`${playhead*zoom}px`}"/></div></div></div></div>
      </section>
      <aside class="inspector-panel"><div class="panel-heading">片段属性</div><template v-if="selected&&draft"><div class="selected-name">{{selected.name}}</div><label>轨道<select v-model="draft.trackId" :disabled="!lease||locked"><option v-for="track in state.tracks.filter(t=>t.kind===(selected!.kind==='audio'?'audio':selected!.kind==='text'?'text':'visual'))" :key="track.id" :value="track.id">{{track.name}}</option></select></label><div class="fields-two"><label>开始 / 帧<input v-model.number="draft.at" type="number" min="0"/></label><label>长度 / 帧<input v-model.number="draft.length" type="number" min="1"/></label></div><small>素材入点 {{selected.in}}f · {{frameTime(selected.length)}}</small><template v-if="selected.kind==='text'"><label>文字<textarea v-model="draft.text"/></label><div class="fields-two"><label>字号<input type="number" v-model.number="draft.fontSize" min="8" max="300"/></label><label>颜色<input type="color" v-model="draft.color"/></label></div><small v-if="selected.precision">字幕精度：{{selected.precision==='character'?'字级对齐':'句级范围'}}</small></template><template v-if="selected.kind!=='audio'"><div class="fields-two"><label>横向位置<input v-model.number="draft.x" type="number"/></label><label>纵向位置<input v-model.number="draft.y" type="number"/></label></div><label v-if="selected.kind!=='text'">缩放<input v-model.number="draft.scale" type="number" min=".05" max="10" step=".05"/></label><label v-if="selected.kind!=='text'">画幅适配<select v-model="draft.fit"><option value="contain">完整显示</option><option value="cover">填满画幅</option><option value="stretch">拉伸</option></select></label></template><template v-if="hasAudioControls"><label>音量<input v-model.number="draft.volume" type="range" min="0" max="4" step=".05"/></label><label class="checkbox"><input type="checkbox" v-model="draft.muted"/>静音</label><div class="fields-two"><label>淡入 / 帧<input type="number" min="0" v-model.number="draft.fadeIn"/></label><label>淡出 / 帧<input type="number" min="0" v-model.number="draft.fadeOut"/></label></div></template><button class="wide accent" :disabled="!canEditSelected||locked" @click="applyProperties">应用属性</button><button v-if="draftDirty" :disabled="locked" @click="selected && select(selected)">放弃本地属性，载入最新</button><button v-if="canUnlink" :disabled="!lease||locked" @click="operate([{type:'unlink_clip',clipId:selected.id}])">{{selected.kind==='text'?'解除字幕关联':'解除音画联动'}}</button><button v-if="hasAudioControls" :disabled="!lease||locked" @click="transcribe">生成中文字幕</button></template><p v-else class="empty-inspector">选择一个片段，调整画面、文字或音频。</p><div class="version-panel"><details @toggle="loadVersions"><summary>历史版本</summary><div v-for="version in versions" :key="version.revision" class="version-row"><span>v{{version.revision}} {{version.message}}</span><button :disabled="!lease||locked||version.revision===revision" @click="restore(version.revision)">恢复</button></div></details></div></aside>
      <aside class="agent-panel"><div class="panel-heading">剪辑 Agent <span>{{plannerModel}}</span></div><div class="messages"><p class="agent-intro">告诉我想保留的区间、素材顺序或字幕要求。生成的素材会先保存到项目素材库。</p><div v-for="(entry,index) in chat" :key="index" :class="['chat-entry',entry.role]">{{entry.text}}</div></div><div v-if="activeRun" class="run-card"><select aria-label="任务历史" :value="activeRun.id" @change="selectRun"><option v-for="run in runs" :key="run.id" :value="run.id">{{run.kind}} · v{{run.revision}} · {{runLabel(run.status)}}</option></select><strong>{{runLabel(activeRun.status)}}</strong><span>{{activeRun.kind}} · v{{activeRun.revision}}</span><p v-if="activeRun.error">{{activeRun.error}}</p><div><button v-if="['queued','running'].includes(activeRun.status)" :disabled="!lease||locked" @click="cancelRun">取消后续步骤</button><button v-if="['error','unknown','lost','awaiting_authorization'].includes(activeRun.status)" :disabled="!lease||locked" @click="retryRun(false)">{{['unknown','lost'].includes(activeRun.status)?'明确重新生成':'重试 / 恢复'}}</button><button v-if="['error','awaiting_authorization'].includes(activeRun.status) && activeRun.kind==='agent'" :disabled="!lease||locked" @click="retryRun(true)">重新规划</button><button v-if="activeRun.status==='error' && ['generation','export','transcription'].includes(activeRun.kind)" :disabled="!lease||locked" @click="retryRun(true)">{{activeRun.kind==='export'?'创建新渲染任务':activeRun.kind==='transcription'?'重新转写':'创建新生成任务'}}</button><button v-if="exportResult" class="accent" @click="saveOpen=true">保存到图库</button><a v-if="exportResult" :href="`${videoBase}/runs/${activeRun.id}/media?download=1`">下载 MP4</a></div></div><div class="agent-input"><textarea v-model="prompt" placeholder="例如：保留第一段前3秒，接第二段，加标题，降低音乐音量" @keydown.ctrl.enter.prevent="sendMessage"/><button class="accent" :disabled="!lease||locked||!prompt.trim()" @click="sendMessage">发送编辑请求</button></div></aside>
    </div></a-spin>
    <a-modal v-model:open="handoffOpen" title="交接编辑权" :confirm-loading="busy" @ok="handoff"><a-input v-model:value="targetId" placeholder="接收成员的用户 ID"/><p>交接后当前会话立即变为只读，接收成员有 60 秒获取编辑权。</p></a-modal>
    <a-modal v-model:open="saveOpen" title="保存成片到图库" @ok="saveVideo"><a-input v-model:value="saveName" placeholder="视频名称"/><p>保存的是导出时固定的 v{{exportResult?.revision}}。项目源文件和素材会继续保留。</p></a-modal>
  </main>
</template>
<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {message} from 'ant-design-vue';import VideoPreview from '@/components/video/VideoPreview.vue';import {videoApi,videoBase,assetMedia,frameTime,type VideoState,type VideoAsset,type VideoClip} from '@/api/videoEditor'
import {restoreHistory} from '@/utils/videoHistory'
import {timelineRows} from '@/utils/videoTimeline'
import {CollaborationGate,leaseFromProject,invalidatesEditing} from '@/utils/videoCollaboration'
const collaboration=new CollaborationGate()
type PendingOperation={path:string;body:any;shared:boolean;history:boolean;previous:number;selectedId:string;draftSnapshot:string|undefined;refreshDraft:boolean}
const pendingOperation=ref<PendingOperation>()
const locked=computed(()=>busy.value||!!pendingOperation.value)
const viewUnavailable=ref(false)
const annotation=ref<any>(),members=ref<any[]>([]),draftBase=ref(1),draftOriginal=ref('')
const draftDirty=computed(()=>!!draft.value && JSON.stringify(draft.value)!==draftOriginal.value)
const canEditSelected=computed(()=>!!selected.value && (!!lease.value || !!annotation.value && (selected.value.kind==='text' || selected.value.kind==='image' && selected.value.overlay)))
async function joinAnnotations(){await leaseAction(async()=>{annotation.value=await videoApi(`/projects/${id}/annotations/lease`,{action:'acquire',sessionId});await load()})}
async function leaveAnnotations(){await leaseAction(async()=>{const held=annotation.value;if(held)await videoApi(`/projects/${id}/annotations/lease`,{action:'release',sessionId,epoch:held.epoch});annotation.value=undefined})}
async function refreshMembers(generation:number){const result=await videoApi(`/projects/${id}/annotations`);if(generation!==loadGeneration)return;members.value=result.members;const held=annotation.value;if(held&&result.serverTime>held.serverTime&&!result.members.some((m:any)=>m.sessionId===sessionId&&Number(m.epoch)===held.epoch)){annotation.value=undefined;error.value='多人编辑资格已失效，本地属性已保留，请重新加入'}}
const route=useRoute(),router=useRouter(),id=String(route.params.id),sessionId=crypto.randomUUID(),project=ref<any>(),state=ref<VideoState>(),revision=ref(1),assets=ref<VideoAsset[]>([]),lease=ref<any>(),loading=ref(true),busy=ref(false),error=ref(''),uploading=ref(false),fileInput=ref<HTMLInputElement>(),selectedId=ref(''),draft=ref<VideoClip>(),playhead=ref(0),playing=ref(false),previewMode=ref('live'),zoom=ref(2),trackKind=ref('visual'),timelineElement=ref<HTMLElement>(),studioFrame=ref<HTMLIFrameElement>(),undo=ref<number[]>([]),redo=ref<number[]>([]),versions=ref<any[]>([]),pictureId=ref(''),modelTool=ref('generate_video'),modelFrames=ref(49),modelPrompt=ref(''),referenceAssetId=ref(''),voiceName=ref('speaker1_a_cn_16k.wav'),voiceOptions=ref(['speaker1_a_cn_16k.wav']),activeRun=ref<any>(),runs=ref<any[]>([]),chat=ref<{role:string;text:string}[]>([]),prompt=ref(''),handoffOpen=ref(false),targetId=ref(''),saveOpen=ref(false),saveName=ref('')
const studioKey=ref(0);let studioReady=false,disconnected=false
let loadGeneration=0
watch(modelTool,tool=>{const reference=assets.value.find(a=>a.id===referenceAssetId.value);if(referenceAssetId.value&&!(tool==='synthesize_speech'?reference?.hasAudio:reference?.kind==='image'))referenceAssetId.value=''})
let renewal:ReturnType<typeof setInterval>|undefined,poller:ReturnType<typeof setInterval>|undefined,stream:EventSource|undefined,animation=0,playStart=0,playStartFrame=0,drag:{clip:VideoClip;mode:string;startX:number;at:number;length:number;trackId:string}|undefined
const duration=computed(()=>state.value?.clips.length?Math.max(...state.value.clips.map(c=>c.at+c.length)):24),selected=computed(()=>state.value?.clips.find(c=>c.id===selectedId.value)),exportResult=computed(()=>activeRun.value?.status==='done'?(activeRun.value.kind==='agent'?activeRun.value.result?.export:activeRun.value.kind==='export'?activeRun.value.result:null):null)
function writeContext(){if(!lease.value)throw Error('请先获取编辑权');return {expectedRevision:revision.value,sessionId,epoch:lease.value.epoch,idempotencyKey:crypto.randomUUID()}}
function fail(e:unknown){disconnected=!(e as any).status||(e as any).status>=500;error.value=(e as Error).message;if(invalidatesEditing(e)){lease.value=undefined;annotation.value=undefined;sendStudioContext()}}
function stopViewing(){
  viewUnavailable.value=true;playing.value=false
  if(!draftDirty.value)draft.value=undefined
  state.value=undefined;project.value=undefined;assets.value=[];members.value=[];lease.value=undefined;annotation.value=undefined
  runs.value=[];activeRun.value=undefined;versions.value=[];chat.value=[];undo.value=[];redo.value=[]
  studioReady=false;studioKey.value++;stream?.close();runGeneration++;sendStudioContext()
}
async function load(refreshOnly=false){const generation=++loadGeneration;try{const result=await videoApi(`/projects/${id}`);if(generation!==loadGeneration)return;await refreshMembers(generation);if(generation!==loadGeneration)return;viewUnavailable.value=false;if(disconnected){error.value='';disconnected=false}const previousLease=lease.value;lease.value=collaboration.reconcile(lease.value,leaseFromProject(result.project),sessionId,result.serverTime);if(previousLease&&!lease.value){undo.value=[];redo.value=[]}if(result.mode==='hypit'){await router.replace(`/video/hypit/${id}`);return}runs.value=result.runs.map((run:any)=>({...run,result:typeof run.result==='string'?JSON.parse(run.result):run.result}));const observedRun=runs.value.find(run=>run.id===activeRun.value?.id);if(observedRun&&observedRun.status!==activeRun.value?.status)void refreshActiveRun?.();if(result.revision<revision.value){sendStudioContext();return}project.value=result.project;assets.value=result.assets;if(refreshOnly&&result.revision===revision.value&&state.value){sendStudioContext();return}if(refreshOnly&&lease.value){undo.value.push(revision.value);redo.value=[]}else if(refreshOnly){undo.value=[];redo.value=[]}if(refreshOnly&&result.revision>revision.value){studioReady=false;sendStudioContext();studioKey.value++}state.value=result.state;revision.value=result.revision;if(!draftDirty.value){if(selected.value)select(selected.value);else draft.value=undefined;}saveName.value ||=result.project.name;if(!activeRun.value&&result.runs.length){const run=result.runs[0];activeRun.value={...run,result:typeof run.result==='string'?JSON.parse(run.result):run.result};if(['running','queued'].includes(run.status))watchRun(run)}sendStudioContext()}catch(e){if(generation!==loadGeneration)return;fail(e);if([401,403,404].includes((e as any).status))stopViewing()}finally{if(generation===loadGeneration)loading.value=false}}
async function leaseAction(fn:()=>Promise<void>){if(locked.value)return;busy.value=true;error.value='';try{await fn()}catch(e){fail(e);if((e as any).status===409)await load(true)}finally{busy.value=false}}
async function acquire(){await leaseAction(async()=>{const acquired=await videoApi(`/projects/${id}/lease`,{action:'acquire',sessionId});if(collaboration.accept(acquired,acquired.serverTime)){lease.value=acquired;undo.value=[];redo.value=[]}sendStudioContext();await load()})}
async function release(){await leaseAction(async()=>{if(lease.value)await videoApi(`/projects/${id}/lease`,{action:'release',sessionId,epoch:lease.value.epoch});lease.value=undefined;undo.value=[];redo.value=[];sendStudioContext()})}
async function handoff(){await leaseAction(async()=>{if(!lease.value)throw Error('请先获取编辑权');await videoApi(`/projects/${id}/lease`,{action:'handoff',sessionId,epoch:lease.value.epoch,targetId:targetId.value});lease.value=undefined;undo.value=[];redo.value=[];handoffOpen.value=false;sendStudioContext()})}
async function operate(operations:any[],history=true,expectedRevision=revision.value,refreshDraft=false){
  if(locked.value)return
  try{
    const shared=!!annotation.value
    const body={...(shared?{expectedRevision,sessionId,epoch:annotation.value.epoch,idempotencyKey:crypto.randomUUID()}:writeContext()),operations}
    pendingOperation.value={path:`/projects/${id}/${shared?'annotations/operations':'operations'}`,body,shared,history,previous:revision.value,selectedId:selectedId.value,draftSnapshot:JSON.stringify(draft.value),refreshDraft:refreshDraft||!draftDirty.value}
    await retryOperation()
  }catch(e){fail(e)}
}
async function retryOperation(){
  const pending=pendingOperation.value
  if(busy.value||!pending)return
  busy.value=true;playing.value=false;error.value=''
  try{
    const result=await videoApi(pending.path,pending.body)
    // A replay returns the original result; another member may already have saved a newer revision.
    if(result.revision>=revision.value){studioReady=false;sendStudioContext();studioKey.value++;state.value=result.state;revision.value=result.revision}
    if(pending.history&&!pending.shared){undo.value.push(pending.previous);redo.value=[]}
    pendingOperation.value=undefined
    await load(true)
    const sameDraft=selectedId.value===pending.selectedId&&JSON.stringify(draft.value)===pending.draftSnapshot
    if(pending.refreshDraft&&sameDraft){if(selected.value)select(selected.value);else draft.value=undefined}
    sendStudioContext()
  }catch(e){
    const status=(e as any).status
    // A response with a client error definitively rejected this request. Network/server errors may have committed it.
